print(count_nums([-1, 11, -11]))  # Output: 1
print(count_nums([1, 1, 2]))  # Output: 3

from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    # Count the occurrences of each letter
    letter_counts = Counter(test.split())

    # Find the maximum occurrence count
    max_count = max(letter_counts.values())

    # Collect all letters that have the maximum occurrence count
    result = {letter: count for letter, count in letter_counts.items() if count == max_count}

    return result

def sort_array(arr):
    def count_ones(n):
        return bin(n).count('1')

    return sorted(arr, key=lambda x: (count_ones(x), x))

# Test cases
print(sort_array([1, 5, 2, 3, 4]))  # Output: [1, 2, 3, 4, 5]
print(sort_array([-2, -3, -4, -5, -6]))  # Output: [-6, -5, -4, -3, -2]
print(sort_array([1, 0, 2, 3, 4]))  # Output: [0, 1, 2, 3, 4]

from collections import Counter

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Count the total number of opening and closing parentheses
    total_open = sum(Counter(lst[0]).values())
    total_close = sum(Counter(lst[1]).values())

    # Check if the total number of opening and closing parentheses are equal
    if total_open != total_close:
        return 'No'

    # Check if either string is already balanced
    if is_balanced(lst[0]) or is_balanced(lst[1]):
        return 'Yes'

    # Try concatenating in both possible orders
    if is_balanced(lst[0] + lst[1]) or is_balanced(lst[1] + lst[0]):
        return 'Yes'

    return 'No'

from datetime import datetime

def valid_date(date):
    # Check if the date string is empty
    if not date:
        return False

    # Check if the date string matches the required format
    try:
        datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    # Extract month and day from the date string
    month, day, year = map(int, date.split('-'))

    # Check if the month is between 1 and 12
    if month < 1 or month > 12:
        return False

    # Check if the day is within the valid range for the given month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    else:  # month is 2 (February)
        if day < 1 or day > 29:
            return False

    return True

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        return sum(1 for char in txt if char.islower() and (ord(char) - ord('a')) % 2 == 1)

# Test cases
print(split_words("Hello world!"))  # ➞ ["Hello", "world!"]
print(split_words("Hello,world!"))  # ➞ ["Hello", "world!"]
print(split_words("abcdef"))      # ➞ 3

def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if stack:
                    nested = True

    return nested

# Test cases
