print(is_nested('[]]]]]]][[[[[]')) ➞ False
print(is_nested('[][]')) ➞ False
print(is_nested('[]')) ➞ False
print(is_nested('[[][]]')) ➞ True
print(is_nested('[[]][[')) ➞ True

def can_arrange(arr):
    for i in range(1, len(arr)):
        if arr[i] >= arr[i - 1]:
            continue
        else:
            return i
    return -1

