def compare_one(a, b):
    def convert_to_float(value):
        if isinstance(value, str):
            value = value.replace(',', '.')
            return float(value)
        return float(value)

    num_a = convert_to_float(a)
    num_b = convert_to_float(b)

    if num_a == num_b:
        return None
    elif num_a > num_b:
        return a
    else:
        return b

