def encode(message):
    def shift_vowel(vowel):
        vowels = "aeiouAEIOU"
        index = vowels.index(vowel)
        return vowels[(index + 2) % len(vowels)]

    encoded_message = ""
    for char in message:
        if char.isalpha():
            if char.islower():
                new_char = char.upper()
            else:
                new_char = char.lower()

            if new_char in "aeiouAEIOU":
                new_char = shift_vowel(new_char)

            encoded_message += new_char
        else:
            encoded_message += char

    return encoded_message

