def remove_parenthesis(items):
    result = []
    for item in items:
        if '(' not in item:
            result.append(item)
        else:
            start = item.find('(')
            end = item.rfind(')')
            if start != -1 and end != -1:
                result.append(item[:start] + item[end+1:])
    return result

from typing import List

def maxAverageOfPath(cost: List[List[int]]) -> float:
    n = len(cost)

    # Initialize the first row and first column
    for i in range(1, n):
        cost[i][0] += cost[i-1][0]
    for j in range(1, n):
        cost[0][j] += cost[0][j-1]

    # Fill the rest of the matrix
    for i in range(1, n):
        for j in range(1, n):
            cost[i][j] += max(cost[i-1][j], cost[i][j-1])

    # The maximum average is the last element divided by the total number of cells
    return cost[-1][-1] / (n * n)

