def last(arr, x):
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] == x:
            result = mid
            left = mid + 1  # Move left to find the last occurrence
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return result

