def get_pairs_count(arr, sum):
    # Create a dictionary to store the frequency of each element in the array
    frequency = {}

    # Count the frequency of each element in the array
    for num in arr:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Initialize the count of pairs
    pair_count = 0

    # Iterate through the array to find pairs
    for num in arr:
        complement = sum - num
        if complement in frequency:
            # If the complement exists in the dictionary, add the frequency of the complement to the pair count
            pair_count += frequency[complement]

    # If the number itself is the complement of itself, we need to subtract one from the pair count
    if sum % 2 == 0 and frequency.get(sum // 2, 0) > 1:
        pair_count -= 1

    return pair_count

