def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        """Calculate the sum of proper divisors of n."""
        divisors_sum = 1  # Start with 1 because it's a proper divisor of every number
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i:  # Avoid adding the square root twice for perfect squares
                    divisors_sum += n // i
        return divisors_sum

    amicable_pairs = set()
    for num in range(2, limit + 1):
        if num not in amicable_pairs:
            partner = sum_of_divisors(num)
            if partner > num and sum_of_divisors(partner) == num:
                amicable_pairs.add(num)
                amicable_pairs.add(partner)

    return sum(amicable_pairs)

