from typing import Optional

def find_solution(a: int, b: int, n: int) -> Optional[tuple]:
    # Check if a and b are coprime
    if gcd(a, b) != 1:
        return None

    # Extended Euclidean algorithm to find x and y
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        x = y1
        y = x1 - (x // y) * y1
        return gcd, x, y

    gcd, x, y = extended_gcd(a, b)

    # If gcd is not 1, no solution exists
    if gcd != 1:
        return None

    # Scale the solution to match the equation ax + by = n
    k = n // gcd
    return (k * x, k * y)

# Helper function to calculate the greatest common divisor
def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def div_sum(n):
    # Calculate the sum of divisors of n
    return sum(i for i in range(1, n + 1) if n % i == 0)

# Example usage:
# print(div_sum(28))  # Output: 28
# print(div_sum(12))  # Output: 28

def find_even_pair(A):
    # Initialize a counter for pairs with even XOR
    even_xor_count = 0

    # Iterate over each pair of elements in the list
    for i in range(len(A)):
        for j in range(i + 1, len(A)):
            # Check if the XOR of the two elements is even
            if (A[i] ^ A[j]) % 2 == 0:
                even_xor_count += 1

    return even_xor_count

# Example usage:
A = [1, 2, 3, 4]
print(find_even_pair(A))  # Output: 6

def next_power_of_2(n):
    if n <= 0:
        return 1
    power = 1
    while power < n:
        power <<= 1
    return power

def perimeter_pentagon(a):
    # A regular pentagon has 5 equal sides
    return 5 * a

def odd_values_string(str):
    # Initialize an empty list to store characters at even indices
    result = []

    # Iterate over the string using enumerate to get both index and character
    for index, char in enumerate(str):
        # Check if the index is even (0-based index)
        if index % 2 == 0:
            # Append the character to the result list
            result.append(char)

    # Join the list into a string and return it
    return ''.join(result)

# Example usage:
print(odd_values_string("abcdef"))  # Output: "ace"
